import json
p='/workspace/run_trace/galaxy_tool_schema/tool_response.json'
d=json.load(open(p))
# recursively print names/types hierarchy
def walk(inputs, indent=0):
    for inp in inputs:
        print('  '*indent, inp.get('type'), inp.get('name'), 'label=',inp.get('label'), 'value=',inp.get('value') or inp.get('default_value'))
        if 'cases' in inp:
            for case in inp['cases']:
                print('  '*(indent+1),'CASE',case.get('value'), case.get('label'))
                walk(case.get('inputs',[]), indent+2)
        if 'inputs' in inp and 'cases' not in inp:
            walk(inp['inputs'], indent+1)
walk(d['inputs'])
PY"

