item.command:
/bin/bash -lc "python3 - <<'PY'
import json
p='/workspace/run_trace/galaxy_tool_schema_003/tool_response.json'
d=json.load(open(p))
# find index options
stack=list(d['inputs'])
while stack:
    x=stack.pop(0)
    if x.get('name')=='index':
        opts=x.get('options', [])
        for label,val,sel in opts:
            if 'hg38' in label.lower() or val in ('hg38','GRCh38','hg19') or 'homo sapiens' in label.lower() or 'human' in label.lower():
                print(label, val)
    for c in x.get('cases',[]): stack.extend(c.get('inputs',[]))
    stack.extend(x.get('inputs',[]) if 'cases' not in x else [])
PY"

