/bin/bash -lc "python3 - <<'PY'
# Reuse downloaded via API quickly and report high-count rankings
import os, urllib.request, csv, math
base=os.environ['GALAXY_URL'].rstrip('/'); history='bbd44e69cb8906b5d8b343407c2a3c9a'
ids={'A':'f9cad7b01a472135bb9090370ebebcbc','B':'f9cad7b01a47213528a35fdec7164453'}
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
counts={}
for sample,ds in ids.items():
    url=base+f'/api/histories/{history}/contents/{ds}/display'
    req=urllib.request.Request(url, headers={'x-api-key':key})
    data=urllib.request.urlopen(req, timeout=60).read().decode()
    d={}
    for r in csv.reader(data.splitlines(), delimiter='\\t'):
        if len(r)>=2 and r[0] "'!= '"'Geneid': d[r[0]]=int(float(r[1]))
    counts[sample]=d
sa=sum(counts['A'].values()); sb=sum(counts['B'].values())
rows=[]
for g in set(counts['A'])|set(counts['B']):
    a=counts['A'].get(g,0); b=counts['B'].get(g,0)
    cpm_a=a/sa*1e6; cpm_b=b/sb*1e6
    lfc=math.log2((cpm_b+0.5)/(cpm_a+0.5))
    rows.append((abs(b-a), abs(cpm_b-cpm_a), abs(lfc), lfc, g, a, b, cpm_a, cpm_b))
for title, key in [('abs_count',0),('abs_cpm',1),('abs_lfc_min20',2)]:
    print('\\n'+title)
    subset=rows
    if title=='abs_lfc_min20': subset=[r for r in rows if max(r[5],r[6])>=20]
    subset=sorted(subset, key=lambda x:x[key], reverse=True)
    for r in subset[:15]:
        print(r[4], 'A', r[5], 'B', r[6], 'diff', r[0], 'lfc', round(r[3],3), 'cpm', round(r[7],2), round(r[8],2))
PY"

